use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let rows = input.as_array().unwrap();
    let mut result = Vec::new();
    for row in rows {
        let key = row.as_array().unwrap().get(0).unwrap().as_i64().unwrap();
        let value = row.as_array().unwrap().get(1).unwrap().as_i64().unwrap();
        result.push(serde_json::Value::from(vec![serde_json::Value::from(key), serde_json::Value::from(value)]));
    }
    result.sort_by_key(|row| row[0].as_i64().unwrap());
    Value::from(result)
}
